const {default: pMap, pMapSkip} = await load('./index.js');
const input = [1, 2, 3];
const mapper = (value, index) => {
  if (index === 0) {
    return pMapSkip;
  }
  return value * 2;
};
const result = await pMap(input, mapper);
assert.deepEqual(result, [4, 6]);
